def load_tables(mast_path: str, stpo_path: str, mast_sep: str = ";", stpo_sep: str = ";") -> tuple[pd.DataFrame, pd.DataFrame]:
    """Lädt MAST und STPO aus CSV-Dateien und normalisiert die Spalten."""
    mast = pd.read_csv(mast_path, sep=mast_sep, dtype=str)
    stpo = pd.read_csv(stpo_path, sep=stpo_sep, dtype=str)

    mast.columns = mast.columns.str.strip().str.upper()
    stpo.columns = stpo.columns.str.strip().str.upper()

    for col in ["MATNR", "STLNR"]:
        if col in mast.columns:
            mast[col] = mast[col].str.strip()

    for col in ["STLNR", "IDNRK", "KNOBJ", "POSTP"]:
        if col in stpo.columns:
            stpo[col] = stpo[col].str.strip()

    if "MENGE" in stpo.columns:
        stpo["MENGE"] = (
            stpo["MENGE"]
            .str.strip()
            .str.replace(",", ".", regex=False)
        )
        stpo["MENGE"] = pd.to_numeric(stpo["MENGE"], errors="coerce").fillna(0)

    return mast, stpo


def load_special_tables(cuob_path: str, cukb_path: str) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Lädt CUOB und CUKB aus XLSX-Dateien und normalisiert die Spalten."""
    cuob = pd.read_excel(cuob_path, dtype=str)
    cukb = pd.read_excel(cukb_path, dtype=str)

    cuob.columns = cuob.columns.str.strip().str.upper()
    cukb.columns = cukb.columns.str.strip().str.upper()

    print("CUOB columns:", cuob.columns.tolist())
    print("CUKB columns:", cukb.columns.tolist())

    for col in ["ZUORDNUNGSNUMMER", "INTERNE NUMMER DES WISSENSBAUSTEINS"]:
        if col in cuob.columns:
            cuob[col] = cuob[col].str.strip()

    for col in ["INTERNE NUMMER DES WISSENSBAUSTEINS", "BEZIEHUNG"]:
        if col in cukb.columns:
            cukb[col] = cukb[col].str.strip()

    return cuob, cukb

