def load_stammdaten(mara_path: str, marc_path: str, sep: str = ";", werks: str = "4000") -> tuple[dict, dict]:
    """Lädt MARA (Warengruppe) und MARC (Disponent) und baut Lookup-Dicts."""
    mara = pd.read_csv(mara_path, sep=sep, dtype=str)
    marc = pd.read_csv(marc_path, sep=sep, dtype=str)

    mara.columns = mara.columns.str.strip().str.upper()
    marc.columns = marc.columns.str.strip().str.upper()

    # MARA: MATNR → MATKL (Warengruppe)
    mara["MATNR"] = mara["MATNR"].str.strip().str.lstrip("0")
    mara["MATKL"] = mara["MATKL"].str.strip() if "MATKL" in mara.columns else ""
    mara_lookup = mara.drop_duplicates("MATNR").set_index("MATNR")["MATKL"].to_dict()

    # MARC: MATNR+WERKS → DISPO (Disponent)
    marc["MATNR"] = marc["MATNR"].str.strip().str.lstrip("0")
    marc["WERKS"] = marc["WERKS"].str.strip() if "WERKS" in marc.columns else ""
    marc["DISPO"] = marc["DISPO"].str.strip() if "DISPO" in marc.columns else ""

    # Nur das relevante Werk
    marc_filtered = marc[marc["WERKS"] == werks].copy()
    marc_lookup = marc_filtered.drop_duplicates("MATNR").set_index("MATNR")["DISPO"].to_dict()

    print(f"MARA-Lookup: {len(mara_lookup)} Materialien")
    print(f"MARC-Lookup: {len(marc_lookup)} Materialien (Werk {werks})")

    return mara_lookup, marc_lookup

