def build_lookups(
    mast: pd.DataFrame,
    stpo: pd.DataFrame,
    stlan: str | None = "1",
    werks: str | None = None,
) -> tuple[dict, dict]:
    """Baut MAST- und STPO-Lookup-Dicts (einmalig, Performance bei vielen Materialien)."""
    mast_filtered = mast.copy()
    if stlan and "STLAN" in mast_filtered.columns:
        mast_filtered = mast_filtered[mast_filtered["STLAN"].str.strip() == stlan]
    if werks and "WERKS" in mast_filtered.columns:
        mast_filtered = mast_filtered[mast_filtered["WERKS"].str.strip() == werks]

    mast_lookup: dict[str, list[str]] = (
        mast_filtered.assign(MATNR_CLEAN=mast_filtered["MATNR"].str.lstrip("0"))
        .groupby("MATNR_CLEAN")["STLNR"]
        .apply(lambda x: x.unique().tolist())
        .to_dict()
    )

    stpo_clean = stpo[stpo["IDNRK"].notna() & (stpo["IDNRK"].str.strip() != "")].copy()
    stpo_lookup: dict[str, list[dict]] = {}
    for stlnr, group in stpo_clean.groupby("STLNR"):
        stpo_lookup[stlnr] = group.to_dict("records")

    return mast_lookup, stpo_lookup


def build_special_lookups(
    cuob: pd.DataFrame,
    cukb: pd.DataFrame,
) -> tuple[dict, dict]:
    """Baut CUOB- und CUKB-Lookup-Dicts (KNOBJ → Wissensbausteine → Beziehungen)."""
    cuob_lookup: dict[str, list[str]] = (
        cuob.assign(ZUORDNUNGSNUMMER_CLEAN=cuob["ZUORDNUNGSNUMMER"].str.lstrip("0"))
        .groupby("ZUORDNUNGSNUMMER_CLEAN")["INTERNE NUMMER DES WISSENSBAUSTEINS"]
        .apply(lambda x: x.unique().tolist())
        .to_dict()
    )

    cukb_lookup: dict[str, list[str]] = (
        cukb.assign(
            WISSENSBAUSTEIN_CLEAN=cukb["INTERNE NUMMER DES WISSENSBAUSTEINS"].str.lstrip("0")
        )
        .groupby("WISSENSBAUSTEIN_CLEAN")["BEZIEHUNG"]
        .apply(lambda x: x.unique().tolist())
        .to_dict()
    )

    return cuob_lookup, cukb_lookup


