def explode_variant_bom_single(
    matnr: str,
    mast_lookup: dict,
    stpo_lookup: dict,
    cuob_lookup: dict,
    cukb_lookup: dict,
    default_profile: dict = DEFAULT_PROFILE,
    manual_defaults: dict = MANUAL_DEFAULTS,
    max_depth: int = 20,
) -> pd.DataFrame:
    """
    Rekursive Stücklistenauflösung MIT Variantenbewertung.
    Nur MATCH und UNCONDITIONAL/SYSTEM_RULE werden weiter aufgelöst.
    Positionen mit POSTP='L' (Lagerposition) werden NICHT weiter aufgelöst.
    """
    matnr = matnr.strip().upper()
    results: list[dict] = []
    queue: list[tuple[str, str | None, int]] = [(matnr, None, 0)]
    visited: set[str] = set()
    while queue:
        current_matnr, parent, level = queue.pop(0)
        if current_matnr in visited or level > max_depth:
            continue
        visited.add(current_matnr)
        stlnr_list = mast_lookup.get(current_matnr.lstrip("0"), [])
        if not stlnr_list:
            continue
        for stlnr in stlnr_list:
            verfuegbare_sh = ermittle_sitzhoehen_pro_parent(
                stlnr, stpo_lookup, cuob_lookup, cukb_lookup
            )
            components = stpo_lookup.get(stlnr, [])
            for comp in components:
                child_matnr = comp["IDNRK"].strip()
                menge = comp.get("MENGE", 0)
                meins = comp.get("MEINS", "").strip() if "MEINS" in comp else ""
                knobj = comp.get("KNOBJ", "").strip() if "KNOBJ" in comp else ""
                postp = comp.get("POSTP", "").strip() if "POSTP" in comp else ""
                status, grund, parsed = bewerte_position(
                    knobj, cuob_lookup, cukb_lookup,
                    default_profile, manual_defaults,
                    verfuegbare_sh if verfuegbare_sh else None,
                )
                results.append({
                    "ebene": level + 1,
                    "materialnummer": child_matnr,
                    "menge": menge,
                    "meins": meins,
                    "postp": postp,
                    "knobj": knobj,
                    "parent_matnr": current_matnr,
                    "variant_status": status.value,
                    "variant_grund": grund,
                    "variant_bedingung": str(parsed) if parsed else "",
                })

                # Nur weiter auflösen wenn Grundversion oder unbedingt

                if child_matnr not in visited:
                    queue.append((child_matnr, current_matnr, level + 1))

    return pd.DataFrame(results)

