def explode_variant_bom_batch(
    matnr_list: list[str],
    mast_lookup: dict,
    stpo_lookup: dict,
    cuob_lookup: dict,
    cukb_lookup: dict,
    default_profile: dict = DEFAULT_PROFILE,
    manual_defaults: dict = MANUAL_DEFAULTS,
    max_depth: int = 20,
) -> pd.DataFrame:
    """
    Löst die Stückliste für eine Liste von Materialnummern auf (mit Variantenfilter).
    Lookups werden von außen übergeben (einmal bauen, oft nutzen).
    """
    all_results: list[pd.DataFrame] = []

    for i, matnr in enumerate(matnr_list, 1):
        matnr_clean = matnr.strip().upper()
        if i % 100 == 0 or i == 1:
            print(f"[{i}/{len(matnr_list)}] {matnr_clean} …")

        bom = explode_variant_bom_single(
            matnr_clean,
            mast_lookup,
            stpo_lookup,
            cuob_lookup,
            cukb_lookup,
            default_profile,
            manual_defaults,
            max_depth,
        )

        if not bom.empty:
            bom.insert(0, "root_matnr", matnr_clean)
            all_results.append(bom)

    if not all_results:
        return pd.DataFrame()

    df = pd.concat(all_results, ignore_index=True)
    return df.sort_values(["root_matnr", "ebene", "parent_matnr"]).reset_index(drop=True)


