# ── Export im SAP-ähnlichen Format ───────────────────────────────────

def export_grundversion_sap_format(
    bom_grundversion: pd.DataFrame,
    mara_lookup: dict,
    marc_lookup: dict,
    werks: str = "4000",
    output_path: str = "grundversion_sap_format.csv",
    sep: str = ";",
):
    """
    Exportiert die Grundversion im Format:
    Werk | Material | ObjektId | Materialkurztext DE | Menge | ME | PTp | Disp. | Warengrp
    
    Erste Zeile pro root_matnr = Kopfzeile (ohne ObjektId, ohne Menge etc.)
    Folgezeilen = Komponenten
    """
    rows: list[dict] = []

    for root_matnr, group in bom_grundversion.groupby("root_matnr", sort=False):
        root_clean = root_matnr.strip().lstrip("0")

        # ── Kopfzeile: Root-Material ─────────────────────────────
        root_dispo = marc_lookup.get(root_clean, "")
        root_matkl = mara_lookup.get(root_clean, "")

        rows.append({
            "Werk": werks,
            "Material": root_matnr,
            "ObjektId": "",
            "Menge": "",
            "ME": "",
            "PTp": "",
            "Disp.": root_dispo,
            "Warengrp": root_matkl,
        })

        # ── Komponentenzeilen ────────────────────────────────────
        for _, row in group.iterrows():
            comp_clean = row["materialnummer"].strip().lstrip("0")
            comp_dispo = marc_lookup.get(comp_clean, "")
            comp_matkl = mara_lookup.get(comp_clean, "")

            # Menge formatieren: Komma statt Punkt
            menge = row.get("menge", 0)
            try:
                menge_str = str(float(menge)).replace(".", ",")
            except (ValueError, TypeError):
                menge_str = str(menge)

            rows.append({
                "Werk": werks,
                "Material": root_matnr,
                "ObjektId": row["materialnummer"],
                "Menge": menge_str,
                "ME": row.get("meins", ""),
                "PTp": row.get("postp", ""),
                "Disp.": comp_dispo,
                "Warengrp": comp_matkl,
            })

    df_export = pd.DataFrame(rows)
    df_export.to_csv(output_path, index=False, sep=sep)
    print(f"SAP-Format exportiert: {len(df_export)} Zeilen → {output_path}")
    return df_export
export_grundversion_sap_format(
    bom_grundversion,
    mara_lookup,
    marc_lookup,
    werks=WERKS,
    output_path="grundversion_sap_format.csv",
    sep=";"
)


